SELECT analytics_order_facts.region, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 10 AND analytics_order_facts.channel = 'wholesale' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_10' AND analytics_order_facts.payment_method = 'bank_transfer' GROUP BY analytics_order_facts.region ORDER BY order_count DESC, analytics_order_facts.region ASC LIMIT 12
